/* =========================================================
   JP SYSTEM · anillo del rest timer, marca y Story Card
========================================================= */
(function(){
  const $$$ = s => document.querySelector(s);

  /* ---------- badge de marca arriba de todo ---------- */
  function badge(){
    /* la certificación ya vive en la barra superior del header Heavy Duty */
    if(document.querySelector('.hd-cert') || document.querySelector('.jp-badge')) return;
    const w = document.createElement('div');
    w.className = 'jp-badge-wrap';
    w.innerHTML = '<div class="jp-badge"><span class="sp">✦</span> Coach JP Performance System' +
                  '<span class="dot"></span> Fitness Program</div>';
    document.body.insertBefore(w, document.body.firstChild);
  }

  /* ---------- anillo conic + botones rápidos del rest timer ---------- */
  function anillo(){
    const hud = document.getElementById('restHud'); if(!hud) return;
    const t = document.getElementById('rhTime');
    if(t && !t.closest('.rh-ring')){
      const ring = document.createElement('div');
      ring.className = 'rh-ring'; ring.id = 'rhRing';
      t.parentNode.insertBefore(ring, t);
      ring.appendChild(t);
    }
    const ctl = hud.querySelector('.rh-ctl');
    if(ctl && !document.getElementById('rhMinus')){
      const m = document.createElement('button');
      var paso = (window.COACH_DISCIPLINA === 'sports') ? 10 : 15;
      m.type = 'button'; m.id = 'rhMinus'; m.textContent = '−' + paso + 's';
      ctl.insertBefore(m, ctl.firstChild);
      m.addEventListener('click', () => { if(window.CoachTV && window.CoachTV.sumar) window.CoachTV.sumar(window.COACH_DISCIPLINA === 'sports' ? -10 : -15); });
    }
    const plus = document.getElementById('rhPlus');
    if(plus) plus.textContent = (window.COACH_DISCIPLINA === 'sports') ? '+10s' : '+15s';
  }

  /* ---------- STORY CARD 9:16 ---------- */
  const W = 1080, H = 1920;
  function redondear(ctx, x, y, w, h, r){
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }
  /* 09/09 -- LUXURY STEALTH: escudo en miniatura para la cabecera de la
     Story Card (estilo Cyber-Grit). Mismo path/gradiente que .hd-shield
     svg (~línea 4197) y que escudoCanvas() del módulo "M5" más abajo
     (~línea 8658) -- se duplica acá adentro (en vez de llamar a la otra
     función) porque esta IIFE corre ANTES que esa y escudoCanvas() no
     queda expuesta en window; total, dibujar() sólo se ejecuta al tocar
     el botón, mucho después de que todos los módulos ya cargaron. */
  function escudoMini(g, cx, cy, alto){
    var s = alto / 74;
    g.save(); g.translate(cx - 32 * s, cy); g.scale(s, s);
    var grad = g.createLinearGradient(0, 0, 64, 74);
    grad.addColorStop(0, '#FFE873'); grad.addColorStop(.38, '#FFD600');
    grad.addColorStop(.72, '#C9A100'); grad.addColorStop(1, '#8A6B00');
    g.fillStyle = grad;
    g.beginPath(); g.moveTo(32, 2); g.lineTo(60, 12); g.lineTo(60, 36);
    g.bezierCurveTo(60, 54, 47, 66, 32, 72); g.bezierCurveTo(17, 66, 4, 54, 4, 36);
    g.lineTo(4, 12); g.closePath(); g.fill();
    g.strokeStyle = '#FFF0A8'; g.lineWidth = 1.6; g.stroke();
    g.fillStyle = '#07080A';
    g.beginPath(); g.moveTo(36, 18); g.lineTo(21, 40); g.lineTo(30, 40);
    g.lineTo(27, 58); g.lineTo(43, 34); g.lineTo(33, 34); g.closePath(); g.fill();
    g.restore();
  }
  /* ---------- FOTO DE FONDO PERSONALIZADA (directiva) ----------
     Estado compartido en window (no en esta IIFE) porque dibujar()/
     dibujarCF()/champion() no viven todas en el mismo closure -- ver
     __storyLast más abajo, que guarda qué función y con qué datos se
     dibujó por última vez, para poder re-pintar cuando el alumno sube o
     saca la foto sin tener que reabrir el modal. */
  window.storyFondoFoto = function(g, Wp, Hp, fallback){
    const img = window.__storyFotoImg;
    if(img && img.complete && img.naturalWidth){
      const ir = img.naturalWidth / img.naturalHeight, cr = Wp / Hp;
      let sw, sh, sx, sy;
      if(ir > cr){ sh = img.naturalHeight; sw = sh * cr; sx = (img.naturalWidth - sw) / 2; sy = 0; }
      else { sw = img.naturalWidth; sh = sw / cr; sx = 0; sy = (img.naturalHeight - sh) / 2; }
      g.drawImage(img, sx, sy, sw, sh, 0, 0, Wp, Hp);
      /* overlay oscuro -- garantiza legibilidad del texto sobre CUALQUIER
         foto, sea clara u oscura (directiva pide 0.60-0.75 de opacidad) */
      const ov = g.createLinearGradient(0, Hp, 0, 0);
      ov.addColorStop(0, 'rgba(0,0,0,0.85)'); ov.addColorStop(1, 'rgba(0,0,0,0.3)');
      g.fillStyle = ov;
      g.fillRect(0, 0, Wp, Hp);
      return true;
    }
    if(typeof fallback === 'function') fallback();
    return false;
  }
  function dibujar(d){
    const c = document.getElementById('storyCanvas');
    const g = c.getContext('2d');
    g.clearRect(0, 0, W, H);
    window.__storyLast = { tipo: 'cyber', d: d };

    /* fondo -- foto de la sesión si el alumno subió una (cover + overlay
       oscuro), si no Dark Stealth Tactical de siempre: gradiente carbón
       profundo #0a0c10 -> #121820, viñeta suave hacia los bordes, reflejos
       sutiles en los colores de marca reales. */
    window.storyFondoFoto(g, W, H, function(){
      let bg = g.createLinearGradient(0, 0, 0, H);
      bg.addColorStop(0, '#0a0c10'); bg.addColorStop(1, '#121820');
      g.fillStyle = bg; g.fillRect(0, 0, W, H);
      let vig = g.createRadialGradient(W / 2, H / 2, H * .28, W / 2, H / 2, H * .72);
      vig.addColorStop(0, 'rgba(0,0,0,0)'); vig.addColorStop(1, 'rgba(0,0,0,.45)');
      g.fillStyle = vig; g.fillRect(0, 0, W, H);
      let r1 = g.createRadialGradient(W * .92, -120, 40, W * .92, -120, 900);
      r1.addColorStop(0, 'rgba(210,121,63,.18)'); r1.addColorStop(1, 'rgba(210,121,63,0)');
      g.fillStyle = r1; g.fillRect(0, 0, W, H);
      let r2 = g.createRadialGradient(-80, H + 120, 40, -80, H + 120, 900);
      r2.addColorStop(0, 'rgba(124,197,232,.14)'); r2.addColorStop(1, 'rgba(124,197,232,0)');
      g.fillStyle = r2; g.fillRect(0, 0, W, H);
    });

    /* marca de agua JP en la esquina, al 3% */
    g.save();
    g.globalAlpha = .03; g.fillStyle = '#FFFFFF';
    g.font = '700 620px "Chakra Petch", sans-serif';
    g.textAlign = 'right'; g.textBaseline = 'alphabetic';
    g.fillText('JP', W - 40, H - 40);
    g.restore();
    jpEsquinasAmbar(g, W, H);

    /* header -- reubicado arriba de todo, 3 líneas (directiva de fix
       integral): [ DÍA X · SEMANA Y ] chico y táctico, el título real de
       la sesión bien grande (protagonista), y la marca COACH JP al pie
       del bloque, nunca al revés. diaCorto/semanaN/tituloSesion vienen
       de inyectarBoton(); si algo llama a dibujar() sin esos campos (un
       caller viejo, o un test), se derivan de sesion/disciplina como
       antes para no romper nada. */
    const diaCorto = d.diaCorto || String(d.sesion || '').split(' · ')[0] || 'DÍA';
    const semanaN = d.semanaN || (function(){ var m = String(d.disciplina || '').match(/(\d+)\s*$/); return m ? m[1] : ''; })();
    const tituloSesion = d.tituloSesion || String(d.sesion || '').split(' · ').slice(1).join(' · ') || d.disciplina || 'Sesión';

    /* atleta, chico, arriba de todo -- se conserva para no perder la
       personalización, pero ya no compite con el título de la sesión */
    g.textAlign = 'left'; g.textBaseline = 'alphabetic';
    var nomAt = (d.atleta || 'ATLETA').toUpperCase(), tamAt = 64;
    g.font = '800 ' + tamAt + 'px "Chakra Petch", sans-serif';
    while(g.measureText(nomAt).width > W - 180 && tamAt > 34){ tamAt -= 2; g.font = '800 ' + tamAt + 'px "Chakra Petch", sans-serif'; }
    g.fillStyle = '#FFFFFF'; g.fillText(nomAt, 90, 138);

    /* línea 1 -- [ DÍA X · SEMANA Y ] a la izquierda, fecha a la derecha */
    var rotulo = '[ ' + diaCorto.toUpperCase() + (semanaN ? ' · SEMANA ' + semanaN : '') + ' ]';
    g.fillStyle = '#38BDF8'; g.font = '700 28px "JetBrains Mono", ui-monospace, monospace';
    g.fillText(rotulo, 90, 190);
    var wRot = g.measureText(rotulo).width, fechaH = jpFechaMil();
    g.font = '700 22px "JetBrains Mono", ui-monospace, monospace';
    if(g.measureText(fechaH).width > W - 180 - wRot - 24) fechaH = fechaH.replace(' · SESSION COMPLETED', '');
    g.textAlign = 'right'; g.fillStyle = 'rgba(245,197,24,.9)'; g.fillText(fechaH, W - 90, 190);
    g.textAlign = 'left';

    /* línea 2 -- título de la sesión, tipografía de alto impacto,
       envuelto hasta 2 líneas si hace falta (mismo helper que ya usaba
       el subtítulo viejo) */
    var tituloLineas;
    (function(){
      var maxW = W - 180, tam = 84, lineas;
      var env = window.CoachEnvolverTexto || function(gg, t){ return [t]; };
      do {
        g.font = '700 ' + tam + 'px "Chakra Petch", sans-serif';
        lineas = env(g, String(tituloSesion).toUpperCase(), maxW, 2);
        if(lineas.length <= 2 && !lineas.recortado) break;
        tam -= 6;
      } while(tam > 48);
      tituloLineas = { lineas: lineas, tam: tam };
      g.fillStyle = '#FFFFFF';
      lineas.forEach(function(ln, i){ g.fillText(ln, 90, 268 + i * (tam + 14)); });
    })();
    var yTrasTitulo = 268 + tituloLineas.lineas.length * (tituloLineas.tam + 14) + 26;

    /* línea volt */
    var yAccent = yTrasTitulo + 20;
    g.fillStyle = '#E5C378'; g.fillRect(90, yAccent, 150, 6);

    /* directiva ("Cálculo real y rediseño de Story Card") -- las 3 cajas
       verticales apiladas (194px cada una + espaciado, ~640px de alto
       total) dejaban muy poco margen para la foto de fondo del atleta.
       Se reemplazan por UNA barra horizontal compacta de 3 columnas,
       anclada al tercio inferior del canvas -- por encima de la franja
       FIJA del pie (racha/top-lift/firma, ver pieYMetricas() más abajo
       en el archivo: siempre redibuja/limpia desde y=1508 hacia abajo,
       así que la barra nunca puede pisar esa zona) -- para dejar el
       resto del canvas (~70%) despejado para la foto. d.vol/d.series
       llegan ya calculados por resumenDatos() (suma kg*reps de TODA
       fila de state.loads con .done=true del día/semana actual, ver
       ese motor más arriba en el archivo) -- nunca 0 si hay series
       tildadas con carga cargada. */
    var barY = 1320, barH = 150, barX = 90, barW = W - 180;
    g.fillStyle = 'rgba(255,255,255,.045)';
    redondear(g, barX, barY, barW, barH, 24); g.fill();
    g.strokeStyle = 'rgba(255,255,255,.10)'; g.lineWidth = 2;
    redondear(g, barX, barY, barW, barH, 24); g.stroke();
    const cols = [
      { icono: '🏋️', v: d.vol.toLocaleString('es-AR') + ' KG', col: '#E5C378', solo: d.vol > 0 },
      { icono: '⚡', v: d.series + ' SERIES', col: '#38BDF8', solo: true },
      { icono: '⏱️', v: String(d.tiempo).toUpperCase(), col: '#FFFFFF', solo: true }
    ].filter(function(cc){ return cc.solo; });      /* sin tonelaje (cardio/WOD) no se dibuja un "0 KG" ficticio */
    const colW = barW / cols.length;
    g.textAlign = 'center'; g.textBaseline = 'middle';
    cols.forEach((cItem, i) => {
      const cx = barX + colW * i + colW / 2;
      if(i > 0){
        g.strokeStyle = 'rgba(255,255,255,.14)'; g.lineWidth = 2;
        g.beginPath(); g.moveTo(barX + colW * i, barY + 26); g.lineTo(barX + colW * i, barY + barH - 26); g.stroke();
      }
      /* icono y valor se miden y se dibujan por separado, con 12px de separacion (gap-3): nunca se montan uno sobre otro */
      let fsCyber = 42, icoW = 0, txtW = 0, conIco = true;
      const GAP_IC = 12, icoTxt = cItem.icono, valTxt = cItem.v, maxColW = colW - 32;
      const fontIco = function(){ return '400 ' + Math.round(fsCyber * 0.95) + 'px "Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif'; };
      const fontVal = function(){ return '700 ' + fsCyber + 'px "Chakra Petch", sans-serif'; };
      const medir = function(){
        g.font = fontVal(); txtW = g.measureText(valTxt).width;
        g.font = fontIco(); icoW = conIco ? g.measureText(icoTxt).width : 0;
        return txtW + (conIco ? GAP_IC + icoW : 0);
      };
      while(medir() > maxColW && fsCyber > 22){ fsCyber -= 2; }
      if(medir() > maxColW){ conIco = false; medir(); }
      const grupoW = txtW + (conIco ? GAP_IC + icoW : 0), x0c = cx - grupoW / 2, yy0 = barY + barH / 2;
      g.textAlign = 'left'; g.textBaseline = 'middle';
      if(conIco){ g.font = fontIco(); g.fillStyle = '#FFFFFF'; g.fillText(icoTxt, x0c, yy0); }
      g.font = fontVal(); g.fillStyle = cItem.col;
      g.fillText(valTxt, x0c + (conIco ? icoW + GAP_IC : 0), yy0);
    });
    g.textAlign = 'left'; g.textBaseline = 'alphabetic';

    /* PR del día -- vive JUSTO ARRIBA de la barra (nunca abajo: ahí ya
       empieza la franja fija del pie) para no restarle más espacio a la
       foto que el estrictamente necesario en un día con marca nueva. */
    if(d.prs && d.prs.length){
      var prH = 118, prY = barY - 24 - prH;
      g.fillStyle = 'rgba(229,195,120,.12)';
      redondear(g, 90, prY, barW, prH, 28); g.fill();
      g.strokeStyle = 'rgba(229,195,120,.45)'; g.lineWidth = 2;
      redondear(g, 90, prY, barW, prH, 28); g.stroke();
      g.fillStyle = '#E5C378'; g.font = '700 40px "Chakra Petch", sans-serif';
      g.fillText('🔥 NUEVA MARCA PERSONAL', 130, prY + 48);
      g.fillStyle = '#FFFFFF';
      /* blindaje de desborde: el texto del PR achica hasta entrar dentro
         del marco dorado (barW menos el padding lateral de 40px por lado)
         y, si ni así entra, se recorta con elipsis -- nunca pasa el borde. */
      var txtPr = d.prs.slice(0, 2).join('  ·  '), fsPr = 30, maxPr = barW - 80;
      g.font = '500 ' + fsPr + 'px Inter, sans-serif';
      while(g.measureText(txtPr).width > maxPr && fsPr > 20){ fsPr -= 2; g.font = '500 ' + fsPr + 'px Inter, sans-serif'; }
      while(txtPr.length > 1 && g.measureText(txtPr).width > maxPr){ txtPr = txtPr.slice(0, -2) + '…'; }
      g.fillText(txtPr, 130, prY + 92);
    }

    /* resumen táctico del día: llena el centro de la tarjeta con los mejores sets, el volumen por ejercicio y el RPE */
    (function(){
      var lista = d.topSets || [];
      var yTop = yAccent + 64, yBot = ((d.prs && d.prs.length) ? (barY - 24 - 118) : barY) - 30;
      if(yBot - yTop < 240) return;
      var px = 90, pw = W - 180, ph = yBot - yTop;
      g.save();
      g.fillStyle = 'rgba(8,12,18,.58)'; redondear(g, px, yTop, pw, ph, 28); g.fill();
      g.strokeStyle = 'rgba(56,189,248,.38)'; g.lineWidth = 2; redondear(g, px, yTop, pw, ph, 28); g.stroke();
      g.textAlign = 'left'; g.textBaseline = 'alphabetic';
      g.fillStyle = '#38BDF8'; g.font = '700 30px "JetBrains Mono", ui-monospace, monospace';
      g.fillText('[ RESUMEN DE SESIÓN ]', px + 44, yTop + 64);
      var rowH = 112, y0 = yTop + 104, pie = (d.rpe ? 84 : 28) + (d.bloquesExtra > 0 ? 48 : 0);
      var maxRows = Math.max(0, Math.floor((ph - 104 - pie) / rowH));
      if(!lista.length){
        var hechosL = d.listaEj || [], tH = 'DÍA COMPLETADO // 100% FOCUS', tamH = 52;
        g.textAlign = 'center'; g.textBaseline = 'alphabetic';
        g.font = '800 ' + tamH + 'px "Chakra Petch", sans-serif';
        while(g.measureText(tH).width > pw - 88 && tamH > 30){ tamH -= 2; g.font = '800 ' + tamH + 'px "Chakra Petch", sans-serif'; }
        var yT = y0 + 24;
        g.fillStyle = '#E5C378'; g.fillText(tH, W / 2, yT);
        var cupo = Math.max(0, Math.floor((ph - 104 - pie - 90) / 52)), mostrar = hechosL.slice(0, cupo);
        g.textAlign = 'left'; g.font = '600 32px Inter, sans-serif'; g.fillStyle = 'rgba(255,255,255,.88)';
        mostrar.forEach(function(nm, i){
          var tt = '✓  ' + String(nm).toUpperCase();
          while(tt.length > 4 && g.measureText(tt).width > pw - 88){ tt = tt.slice(0, -2); }
          g.fillText(tt, px + 44, yT + 74 + i * 52);
        });
        if(hechosL.length > mostrar.length && mostrar.length){
          g.fillStyle = 'rgba(255,255,255,.5)'; g.fillText('+ ' + (hechosL.length - mostrar.length) + ' más', px + 44, yT + 74 + mostrar.length * 52);
        }
      }
      lista.slice(0, maxRows).forEach(function(it, i){
        var yy = y0 + i * rowH;
        if(i > 0){ g.strokeStyle = 'rgba(255,255,255,.10)'; g.lineWidth = 2; g.beginPath(); g.moveTo(px + 44, yy - 22); g.lineTo(px + pw - 44, yy - 22); g.stroke(); }
        var der = it.kg + ' KG × ' + it.reps;
        g.font = '800 40px "Chakra Petch", sans-serif';
        var wDer = g.measureText(der).width;
        var nom = String(it.ex).toUpperCase(), maxN = pw - 88 - wDer - 30;
        g.font = '700 36px "Chakra Petch", sans-serif';
        while(nom.length > 3 && g.measureText(nom).width > maxN){ nom = nom.slice(0, -2); }
        if(nom.length < String(it.ex).length) nom = nom.replace(/\s+$/, '') + '…';
        g.textAlign = 'left'; g.fillStyle = '#FFFFFF'; g.fillText(nom, px + 44, yy + 18);
        g.font = '800 40px "Chakra Petch", sans-serif';
        g.textAlign = 'right'; g.fillStyle = '#E5C378'; g.fillText(der, px + pw - 44, yy + 18);
        g.textAlign = 'left'; g.fillStyle = 'rgba(255,255,255,.5)'; g.font = '600 26px "JetBrains Mono", ui-monospace, monospace';
        g.fillText('VOL ' + it.vol.toLocaleString('es-AR') + ' KG', px + 44, yy + 58);
      });
      if(d.bloquesExtra > 0 && lista.length){
        g.textAlign = 'left'; g.fillStyle = 'rgba(255,255,255,.45)'; g.font = '600 28px Inter, sans-serif';
        g.fillText('+ ' + d.bloquesExtra + (d.bloquesExtra === 1 ? ' bloque m\u00e1s completado' : ' bloques m\u00e1s completados'), px + 44, yTop + ph - (d.rpe ? 82 : 34));
      }
      if(d.rpe){
        g.textAlign = 'left'; g.fillStyle = '#38BDF8'; g.font = '700 32px "JetBrains Mono", ui-monospace, monospace';
        g.fillText('🎯 RPE REGISTRADO: ' + d.rpe, px + 44, yTop + ph - 34);
      }
      g.restore();
    })();

    /* el pie lo escribe el módulo de métricas: racha, top lift y firma */
    g.textAlign = 'center';
    return c;
  }

  /* directiva9 -- formatea minutos de sesión en "XX min" (<60) o "Xh YYm"
     (>=60), para el contador del Story Card. */
  /* fecha en estilo militar compacto ("// 03.OCT.2026 · SESSION COMPLETED") y
     esquinas ⌈ ⌉ ⌊ ⌋ ámbar -- compartidas por la Story de Sports y la de CrossFit */
  window.jpFechaMil = function(){
    var MES = ['ENE','FEB','MAR','ABR','MAY','JUN','JUL','AGO','SEP','OCT','NOV','DIC'], h = new Date();
    return '// ' + ('0' + h.getDate()).slice(-2) + '.' + MES[h.getMonth()] + '.' + h.getFullYear() + ' · SESSION COMPLETED';
  };
  window.jpEsquinasAmbar = function(g, Wc, Hc){
    g.save();
    g.strokeStyle = '#F5C518'; g.lineWidth = 6; g.lineCap = 'square';
    g.shadowColor = 'rgba(245,197,24,.55)'; g.shadowBlur = 14;
    var m = 44, bl = 86;
    [[m, m, 1, 1], [Wc - m, m, -1, 1], [m, Hc - m, 1, -1], [Wc - m, Hc - m, -1, -1]].forEach(function(p){
      g.beginPath(); g.moveTo(p[0], p[1] + bl * p[3]); g.lineTo(p[0], p[1]); g.lineTo(p[0] + bl * p[2], p[1]); g.stroke();
    });
    g.restore();
  };
  function fmtDuracionStory(mins){
    var m = Math.max(1, Math.round(mins || 0));
    if(m < 60) return m + ' min';
    var h = Math.floor(m / 60), rem = m % 60;
    return h + 'h ' + String(rem).padStart(2, '0') + 'm';
  }

  /* ---------- STORY CARD EXCLUSIVA CROSSFIT / HYROX ----------
     Formato propio (no reutiliza dibujar(), pensado para hipertrofia):
     kilos clave del bloque de fuerza/skill, estructura del WOD/Metcon y
     el score final destacado en Cyan Táctico, en vez de volumen/series. */
  function dibujarCF(d){
    const c = document.getElementById('storyCanvas');
    const g = c.getContext('2d');
    g.clearRect(0, 0, W, H);
    window.__storyLast = { tipo: 'cf', d: d };
    /* debug -- geometría real de cada hero card dibujada (no solo
       medida), para poder validar en tests que nunca se superponen sin
       tener que hacer forense de píxeles sobre el canvas. */
    window.__storyRects = [];

    window.storyFondoFoto(g, W, H, function(){
      let bg = g.createLinearGradient(0, 0, 0, H);
      bg.addColorStop(0, '#05070A'); bg.addColorStop(1, '#0D1117');
      g.fillStyle = bg; g.fillRect(0, 0, W, H);
      g.save();
      g.fillStyle = 'rgba(255,255,255,.05)';
      for(let yy = 20; yy < H; yy += 40){
        for(let xx = 20; xx < W; xx += 40){ g.beginPath(); g.arc(xx, yy, 1.4, 0, Math.PI * 2); g.fill(); }
      }
      g.restore();
      let vig = g.createRadialGradient(W / 2, H / 2, H * .25, W / 2, H / 2, H * .75);
      vig.addColorStop(0, 'rgba(0,0,0,0)'); vig.addColorStop(1, 'rgba(0,0,0,.55)');
      g.fillStyle = vig; g.fillRect(0, 0, W, H);
    });

    /* marco táctico -- esquinas tipo bracket, mismo lenguaje visual que
       los "[ ]" de la Pizarra */
    /* directiva maestra ("Story Card táctica"): esquinas ⌈ ⌉ ⌊ ⌋ en ámbar/dorado definido */
    g.save();
    g.strokeStyle = '#F5C518'; g.lineWidth = 6; g.lineCap = 'square';
    g.shadowColor = 'rgba(245,197,24,.55)'; g.shadowBlur = 14;
    const m = 44, bl = 86;
    [[m, m, 1, 1], [W - m, m, -1, 1], [m, H - m, 1, -1], [W - m, H - m, -1, -1]].forEach(function(p){
      g.beginPath();
      g.moveTo(p[0], p[1] + bl * p[3]);
      g.lineTo(p[0], p[1]);
      g.lineTo(p[0] + bl * p[2], p[1]);
      g.stroke();
    });
    g.restore();

    /* escudo superior con destello eléctrico cyan */
    let glow = g.createRadialGradient(W / 2, 150, 10, W / 2, 150, 220);
    glow.addColorStop(0, 'rgba(56,189,248,.35)'); glow.addColorStop(1, 'rgba(56,189,248,0)');
    g.fillStyle = glow; g.fillRect(0, 0, W, 320);

    /* directiva ("Rediseño Story Card 9:16") -- línea de marca chica
       arriba del badge táctico: "COACH JP · HIGH PERFORMANCE SYSTEM",
       mismo texto institucional que ya usa dibujar() (estilo Bodybuilding)
       en su propio encabezado, ahora también en la versión CrossFit. */
    g.textAlign = 'center'; g.textBaseline = 'alphabetic';
    g.fillStyle = '#38BDF8'; g.font = '700 30px "JetBrains Mono", ui-monospace, monospace';
    g.fillText('[ CROSSFIT & HYROX TACTICAL ]', W / 2, 200);

    /* directiva (rediseño total Story Card 9:16, ultra profesional) --
       el header ahora manda con el NOMBRE DEL ATLETA en tipografía
       impactante (antes el protagonista era "COACH JP · <título del
       WOD>", que competía visualmente con las cards de abajo); el
       título/estructura del WOD pasa a vivir DENTRO de su propia hero
       card, nunca en el header. Cuerpo reducido a DOS hero cards
       protagonistas (Fuerza/Skill y WOD/Metcon) en vez de 3+ cajitas
       chicas -- cada una mide su alto real ANTES de dibujarse (nunca
       desborda, nunca deja aire de más) y si sólo existe una de las dos
       (o ninguna), se centra en todo el espacio disponible para que el
       lienzo nunca luzca "vacío". */
    var env = window.CoachEnvolverTexto || function(gg, t){ return [t]; };
    var nombreLineas;
    (function(){
      var maxW = W - 160, tam = 84, lineas;
      do {
        g.font = '900 ' + tam + 'px "Plus Jakarta Sans", sans-serif';
        lineas = env(g, (d.atleta || 'ATLETA').toUpperCase(), maxW, 2);
        if(lineas.length <= 2 && !lineas.recortado) break;
        tam -= 6;
      } while(tam > 48);
      nombreLineas = { lineas: lineas, tam: tam };
      g.textAlign = 'center'; g.fillStyle = '#FFFFFF';
      lineas.forEach(function(ln, i){ g.fillText(ln, W / 2, 296 + i * (tam + 8)); });
    })();
    var yTrasNombre = 296 + nombreLineas.lineas.length * (nombreLineas.tam + 8) + 14;

    g.textAlign = 'center';
    /* fecha en estilo militar compacto: "// 03.OCT.2026 · SESSION COMPLETED" */
    var fechaMil = (function(){
      var MES = ['ENE','FEB','MAR','ABR','MAY','JUN','JUL','AGO','SEP','OCT','NOV','DIC'], hoyD = new Date();
      return '// ' + ('0' + hoyD.getDate()).slice(-2) + '.' + MES[hoyD.getMonth()] + '.' + hoyD.getFullYear() + ' · SESSION COMPLETED';
    })();
    g.fillStyle = 'rgba(245,197,24,.9)'; g.font = '700 27px "JetBrains Mono", ui-monospace, monospace';
    g.fillText(fechaMil, W / 2, yTrasNombre);

    g.fillStyle = '#E06D2D'; g.fillRect(W / 2 - 75, yTrasNombre + 30, 150, 6);
    var y = yTrasNombre + 30 + 6 + 54;

    var footerReserve = 240;
    var footerTop = H - footerReserve;

    /* hero card glassmorphism: rótulo + título (opcional) + métrica
       gigante (opcional). soloMedir=true corre exactamente la misma
       lógica de medición (g.font/env/measureText, sin efecto visual) sin
       dibujar nada -- permite decidir el alto REAL antes de decidir el
       layout final (centrado si sólo hay una card). */
    /* directiva ("Composición Universal de Movimientos") -- nuevo
       parámetro "subtitulo": línea chica de chips debajo del título
       (ej. "SNATCH COMPLEX · BACK SQUAT WAVE"), para separar la
       categoría dinámica del título ("OLYMPIC LIFTING & STRENGTH") de
       los nombres reales de los bloques trabajados. Opcional -- las
       demás cards (WOD, vacío) siguen pasando '' sin cambiar su layout. */
    function heroCard(x0, y0, w, hMax, label, colorAccent, titulo, subtitulo, captionMetrica, metrica, badgeTxt, soloMedir){
      var padX = 46, padTop = 44;
      var tituloTam = 46, tituloLineas2 = [], tituloLH = 0;
      if(titulo){
        var tam2 = tituloTam;
        do {
          g.font = '800 ' + tam2 + 'px "Plus Jakarta Sans", sans-serif';
          tituloLineas2 = env(g, String(titulo).toUpperCase(), w - padX * 2, 2);
          if(tituloLineas2.length <= 2 && !tituloLineas2.recortado) break;
          tam2 -= 3;
        } while(tam2 > 30);
        tituloTam = tam2;
        tituloLH = Math.round(tituloTam * 1.22);
      }
      var labelH = 58;
      var tituloBlockH = tituloLineas2.length ? (tituloLineas2.length * tituloLH + 18) : 0;
      var subTam = 25, subLineas = [], subLH = 0;
      if(subtitulo){
        g.font = '600 ' + subTam + 'px "JetBrains Mono", monospace';
        subLineas = env(g, String(subtitulo).toUpperCase(), w - padX * 2, 2);
        subLH = Math.round(subTam * 1.3);
      }
      var subBlockH = subLineas.length ? (subLineas.length * subLH + 14) : 0;
      /* directiva ("Ajuste de Encuadre de Story Card") -- antes la métrica
         gigante (ej. un score/estructura largo tipo "EVERY 6:00 X 5
         SETS...") era SIEMPRE una sola línea que sólo se achicaba hasta
         un piso de 54px sin garantía de caber: si a 54px todavía no
         entraba, se dibujaba igual y colapsaba contra el borde/padding
         de la tarjeta. Mismo patrón ya probado de nombreLineas/
         tituloLineas2 -- envuelve hasta 2 líneas dentro de w - padX*2,
         nunca desborda el padding interno de la card. */
      var fsM = 0, metricaLineas = [], metricaLH = 0;
      if(metrica){
        var tamM = 120, metricaTxt = String(metrica);
        do {
          g.font = '900 ' + tamM + 'px "Plus Jakarta Sans", sans-serif';
          metricaLineas = env(g, metricaTxt, w - padX * 2, 2);
          if(metricaLineas.length <= 2 && !metricaLineas.recortado) break;
          tamM -= 6;
        } while(tamM > 40);
        fsM = tamM;
        metricaLH = Math.round(fsM * 1.18);
      }
      var captionH = captionMetrica ? 42 : 0;
      var metricaH = metrica ? (metricaLineas.length * metricaLH + 20) : 0;
      /* directiva ("Story Card de alto impacto") -- badge destacado
         (🔥 TOP LIFT / 🔥 NUEVO PR) como pastilla chica debajo de la
         métrica gigante, nunca compitiendo en tamaño con ella. */
      var badgeH = badgeTxt ? 66 : 0;
      /* FIX CRÍTICO ("Eliminación de superposiciones") -- este alto se
         usa DESPUÉS para posicionar la card siguiente (yStart + hSkill +
         gap). Antes se recortaba a hMax vía Math.min(hMax, natural) --
         pero el DIBUJADO de abajo nunca respetaba ese recorte, seguía
         escribiendo TODOS los elementos con su alto natural completo. El
         resultado: si el contenido real (título + subtítulo + métrica +
         badge) superaba hMax, la card se reportaba más baja de lo que en
         verdad medía, la siguiente card arrancaba antes de que la
         anterior terminara de dibujarse, y el badge de Top Lift quedaba
         literalmente montado sobre el borde de la card del WOD -- el bug
         reportado. Ahora el alto devuelto SIEMPRE es el natural real (sin
         recorte a hMax): la card puede terminar más alta que "lo
         preferido", pero jamás miente sobre cuánto espacio ocupa de
         verdad, así que nunca se superpone con lo que viene después. */
      var h = Math.max(220, padTop + labelH + tituloBlockH + subBlockH + captionH + metricaH + badgeH + 40);

      if(!soloMedir){
        if(window.__storyRects) window.__storyRects.push({ label: label, x0: x0, y0: y0, w: w, h: h });
        g.save();
        redondear(g, x0, y0, w, h, 34);
        var gradGlass = g.createLinearGradient(x0, y0, x0, y0 + h);
        gradGlass.addColorStop(0, 'rgba(255,255,255,.10)'); gradGlass.addColorStop(1, 'rgba(255,255,255,.03)');
        g.fillStyle = gradGlass; g.fill();
        g.strokeStyle = 'rgba(255,255,255,.18)'; g.lineWidth = 2; redondear(g, x0, y0, w, h, 34); g.stroke();
        redondear(g, x0, y0, w, 8, 34); g.fillStyle = colorAccent; g.fill();
        g.restore();

        var cy = y0 + padTop;
        g.textAlign = 'left';
        g.fillStyle = colorAccent; g.font = '700 27px "JetBrains Mono", monospace';
        g.fillText('[ ' + label + ' ]', x0 + padX, cy + 20);
        cy += labelH;
        if(tituloLineas2.length){
          g.fillStyle = '#FFFFFF';
          g.font = '800 ' + tituloTam + 'px "Plus Jakarta Sans", sans-serif';
          tituloLineas2.forEach(function(ln, i){ g.fillText(ln, x0 + padX, cy + Math.round(tituloLH * .82) + i * tituloLH); });
          cy += tituloBlockH;
        }
        if(subLineas.length){
          g.fillStyle = 'rgba(255,255,255,.62)';
          g.font = '600 ' + subTam + 'px "JetBrains Mono", monospace';
          subLineas.forEach(function(ln, i){ g.fillText(ln, x0 + padX, cy + Math.round(subLH * .82) + i * subLH); });
          cy += subBlockH;
        }
        if(captionMetrica){
          g.fillStyle = 'rgba(255,255,255,.5)'; g.font = '700 24px "JetBrains Mono", monospace';
          g.fillText(captionMetrica, x0 + padX, cy + 22);
          cy += captionH;
        }
        if(metrica){
          g.fillStyle = colorAccent; g.font = '900 ' + fsM + 'px "Plus Jakarta Sans", sans-serif';
          metricaLineas.forEach(function(ln, i){ g.fillText(ln, x0 + padX, cy + Math.round(fsM * .86) + i * metricaLH); });
          cy += metricaH;
        }
        if(badgeTxt){
          var fsB = 26;
          g.font = '800 ' + fsB + 'px "JetBrains Mono", monospace';
          var bw = g.measureText(badgeTxt).width + 44;
          var bh = 46;
          g.fillStyle = 'rgba(245,197,24,.14)'; redondear(g, x0 + padX, cy + 6, bw, bh, 23); g.fill();
          g.strokeStyle = 'rgba(245,197,24,.5)'; g.lineWidth = 2; redondear(g, x0 + padX, cy + 6, bw, bh, 23); g.stroke();
          g.fillStyle = '#F5C518';
          g.fillText(badgeTxt, x0 + padX + 22, cy + 6 + bh / 2 + 9);
        }
      }
      return h;
    }

    var tieneSkill = !!(d.skillTitulo || d.kgClave || d.volumenTotal > 0 || d.topLiftKg > 0);
    var tieneWod = !!(d.estructura || d.score);
    /* directiva ("Fix definitivo Story Card 9:16") -- la píldora de
       Corework/Accesorios se retira del todo: el canvas 9:16 se centra
       exclusivamente en las 2 Hero Cards (Fuerza/Skill y Metcon/WOD),
       sin un tercer elemento que sobrecargue la lectura. Todo el cuerpo
       entre el header y el footer queda disponible para esas 2 cards. */
    var bodyBottom = footerTop - 26;
    var bodyH = Math.max(240, bodyBottom - y);
    var gap = 44;
    var wCard = W - 180;

    /* directiva -- Hero Card 1 (STRENGTH & TONNAGE): la métrica
       protagonista pasa de "carga máxima puntual" a VOLUMEN TOTAL de la
       sesión (impacto real de todo el trabajo hecho, no de una sola
       serie); el top lift/PR pasa a badge secundario debajo. */
    var skillCaption = d.volumenTotal > 0 ? 'VOLUMEN TOTAL' : (d.kgClave ? 'CARGA MÁXIMA (KG)' : '');
    var skillMetrica = d.volumenTotal > 0 ? (d.volumenTotal.toLocaleString('es-AR') + ' KG') : (d.kgClave || '');
    var skillBadge = d.topLiftKg > 0 ? ('🔥 ' + (d.esPR ? 'NUEVO PR' : 'TOP LIFT') + ': ' + (Number.isInteger(d.topLiftKg) ? d.topLiftKg : Math.round(d.topLiftKg * 10) / 10) + ' KG') : '';

    if(tieneSkill && tieneWod){
      var hMaxSkill = Math.round(bodyH * .42);
      var hSkill = heroCard(90, y, wCard, hMaxSkill, 'FUERZA / SKILL', '#E06D2D', d.skillTitulo, d.skillChips, skillCaption, skillMetrica, skillBadge, true);
      var hMaxWod = bodyH - hSkill - gap;
      var hWod = heroCard(90, y + hSkill + gap, wCard, hMaxWod, 'METCON / WOD', '#38BDF8', d.wodTitulo || d.estructura, d.wodTitulo ? d.estructura : '', d.score ? 'SCORE FINAL' : '', d.score || '', '', true);
      var sobra = Math.max(0, bodyH - hSkill - gap - hWod);
      var yStart = y + Math.round(sobra / 2);
      heroCard(90, yStart, wCard, hMaxSkill, 'FUERZA / SKILL', '#E06D2D', d.skillTitulo, d.skillChips, skillCaption, skillMetrica, skillBadge, false);
      heroCard(90, yStart + hSkill + gap, wCard, hMaxWod, 'METCON / WOD', '#38BDF8', d.wodTitulo || d.estructura, d.wodTitulo ? d.estructura : '', d.score ? 'SCORE FINAL' : '', d.score || '', '', false);
    } else if(tieneSkill || tieneWod){
      var soloLabel = tieneSkill ? 'FUERZA / SKILL' : 'METCON / WOD';
      var soloColor = tieneSkill ? '#E06D2D' : '#38BDF8';
      var soloTitulo = tieneSkill ? d.skillTitulo : (d.wodTitulo || d.estructura);
      var soloSubtitulo = tieneSkill ? d.skillChips : (d.wodTitulo ? d.estructura : '');
      var soloCaption = tieneSkill ? skillCaption : (d.score ? 'SCORE FINAL' : '');
      var soloMetrica = tieneSkill ? skillMetrica : (d.score || '');
      var soloBadge = tieneSkill ? skillBadge : '';
      var hSolo = heroCard(90, y, wCard, bodyH, soloLabel, soloColor, soloTitulo, soloSubtitulo, soloCaption, soloMetrica, soloBadge, true);
      var yCentrada = y + Math.max(0, Math.round((bodyH - hSolo) / 2));
      heroCard(90, yCentrada, wCard, bodyH, soloLabel, soloColor, soloTitulo, soloSubtitulo, soloCaption, soloMetrica, soloBadge, false);
    } else {
      var hVacio = heroCard(90, y, wCard, bodyH, 'SESIÓN', '#7CC5E8', d.tituloWod || 'ENTRENAMIENTO', '', '', '', '', true);
      var yVacia = y + Math.max(0, Math.round((bodyH - hVacio) / 2));
      heroCard(90, yVacia, wCard, bodyH, 'SESIÓN', '#7CC5E8', d.tituloWod || 'ENTRENAMIENTO', '', '', '', '', false);
    }

    /* FOOTER: sello Coach JP + badge Session Completed (directiva) --
       zona reservada fija (footerReserve), el cuerpo nunca dibuja acá. */
    g.textAlign = 'center';
    /* (el "SESSION COMPLETED" ya vive en la línea de fecha del encabezado) */

    /* directiva ("Actualización del footer de marca") -- frase
       institucional exacta pedida: "COACH JP · DISCIPLINE EQUALS
       FREEDOM" (reemplaza "COACH JP · HIGH PERFORMANCE"). Es más larga,
       así que la píldora se dimensiona a partir del ancho real medido
       (mismo patrón que el badge de heroCard) en vez de un ancho fijo
       que la hubiera cortado. */
    var footerFrase = '⚡ PROGRAMMED BY @COACHJP';
    g.font = '700 22px "JetBrains Mono", monospace';
    var footerW = g.measureText(footerFrase).width + 64;
    g.fillStyle = 'rgba(245,197,24,.14)'; redondear(g, W / 2 - footerW / 2, H - 106, footerW, 58, 29); g.fill();
    g.strokeStyle = 'rgba(245,197,24,.5)'; g.lineWidth = 2; redondear(g, W / 2 - footerW / 2, H - 106, footerW, 58, 29); g.stroke();
    g.fillStyle = '#F5C518';
    g.fillText(footerFrase, W / 2, H - 68);

    return c;
  }

  function abrirStory(d){
    var pintar = function(){ if(typeof window.CoachStoryMarca === 'function' && window.COACH_DISCIPLINA === 'sports') window.CoachStoryMarca(d); else dibujar(d); };
    if(document.fonts && document.fonts.ready){
      document.fonts.ready.then(pintar).catch(pintar);
    }
    pintar();
    document.getElementById('storyWrap').classList.add('on');
    try{ if(navigator.vibrate) navigator.vibrate([40, 40, 80]); }catch(e){}
  }
  function abrirCF(d){
    var pintarCF = function(){ if(typeof window.CoachStoryMarcaCF === 'function' && window.COACH_DISCIPLINA !== 'sports') window.CoachStoryMarcaCF(d); else dibujarCF(d); };
    if(document.fonts && document.fonts.ready){
      document.fonts.ready.then(pintarCF).catch(pintarCF);
    }
    pintarCF();
    document.getElementById('storyWrap').classList.add('on');
    try{ if(navigator.vibrate) navigator.vibrate([40, 40, 80]); }catch(e){}
  }
  function cerrarStory(){ document.getElementById('storyWrap').classList.remove('on'); }

  document.getElementById('storyX').addEventListener('click', cerrarStory);
  document.getElementById('storyWrap').addEventListener('click', e => {
    if(e.target.id === 'storyWrap') cerrarStory();
  });
  /* directiva ("Fix descarga/guardado nativo de imagen") -- en iPhone
     (Safari/PWA) el atributo download de un <a> con un Data URL o Blob
     es bloqueado o ignorado en silencio por WebKit: el alumno tocaba
     "Descargar" y no pasaba nada, sin ningún error visible. Web Share
     API con soporte de archivos (navigator.canShare({files})) es la vía
     confiable en iOS -- abre el Action Sheet nativo (Guardar en Fotos/
     Copiar/compartir directo a Instagram o WhatsApp). Android/desktop
     (o iOS viejo sin soporte de archivos en Share) caen al link
     <a download> de siempre, con Blob + Object URL en vez de Data URL
     (más liviano, sin el límite de tamaño de un data: URI); si ESE
     también fallara en algún WebKit raro, el último respaldo abre la
     imagen en una pestaña nueva con la instrucción de mantener
     presionado para guardarla a mano -- nunca falla en silencio. */
  /* texto de un botón de la Story: el <span class="sa-tx"> (el icono SVG no se pisa) */
  function sTx(btn){ return btn.querySelector('.sa-tx') || btn; }
  function storyDescargaFallback(blob, nombreArchivo, btn, textoOriginal, restaurar){
    try{
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.download = nombreArchivo;
      a.href = url;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(function(){ URL.revokeObjectURL(url); }, 4000);
      sTx(btn).textContent = 'Descargada ✓';
      restaurar(textoOriginal, 2200);
    }catch(e){
      try{
        const url2 = URL.createObjectURL(blob);
        window.open(url2, '_blank');
        sTx(btn).textContent = 'Mantené presionado para guardar';
      }catch(e2){ sTx(btn).textContent = 'Usá Copiar'; }
      restaurar(textoOriginal, 3600);
    }
  }
  document.getElementById('storyDl').addEventListener('click', function(){
    const btn = this;
    const textoOriginal = sTx(btn).textContent;
    const restaurar = function(txt, delay){ setTimeout(function(){ sTx(btn).textContent = txt; }, delay); };
    const c = document.getElementById('storyCanvas');
    btn.disabled = true;
    c.toBlob(function(blob){
      btn.disabled = false;
      if(!blob){ sTx(btn).textContent = 'No se pudo generar'; restaurar(textoOriginal, 2200); return; }
      const nombreArchivo = 'coach-jp-story.png';
      let file = null;
      try{ file = new File([blob], nombreArchivo, { type: 'image/png' }); }catch(e){}
      if(file && navigator.canShare && navigator.canShare({ files: [file] })){
        navigator.share({ files: [file], title: 'Story Coach JP' })
          .then(function(){ sTx(btn).textContent = 'Compartida ✓'; restaurar(textoOriginal, 2200); })
          .catch(function(err){
            /* el alumno cerró el Action Sheet sin elegir nada -- no es un
               error real, se restaura el botón en silencio */
            if(err && err.name === 'AbortError'){ sTx(btn).textContent = textoOriginal; return; }
            storyDescargaFallback(blob, nombreArchivo, btn, textoOriginal, restaurar);
          });
        return;
      }
      storyDescargaFallback(blob, nombreArchivo, btn, textoOriginal, restaurar);
    }, 'image/png');
  });
  document.getElementById('storyCp').addEventListener('click', function(){
    const b = this, c = document.getElementById('storyCanvas');
    const fallo = function(){ sTx(b).textContent = 'Usá Descargar'; setTimeout(function(){ sTx(b).textContent = 'Copiar'; }, 2600); };
    try{
      c.toBlob(function(blob){
        if(!blob || !navigator.clipboard || !window.ClipboardItem){ fallo(); return; }
        navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })])
          .then(function(){ sTx(b).textContent = 'Copiada ✓'; setTimeout(function(){ sTx(b).textContent = 'Copiar'; }, 2200); })
          .catch(fallo);
      }, 'image/png');
    }catch(e){ fallo(); }
  });

  /* ---------- foto de fondo personalizada (directiva) ----------
     __storyLast (seteado al tope de dibujar/dibujarCF/champion) guarda
     con qué función y datos se pintó la tarjeta por última vez, así el
     redibujado post-foto no depende de reabrir el modal ni de saber a
     mano qué estilo estaba activo. */
  function redibujarStoryActual(){
    const last = window.__storyLast;
    if(!last || !last.d) return;
    if(last.tipo === 'cf'){
      if(window.CoachStory && typeof window.CoachStory.abrirCF === 'function') window.CoachStory.abrirCF(last.d);
    } else if(window.CoachStory && typeof window.CoachStory.abrir === 'function'){
      const estiloAntes = (window.CoachStoryStyles && typeof window.CoachStoryStyles.actual === 'function') ? window.CoachStoryStyles.actual() : null;
      window.CoachStory.abrir(last.d);
      if(estiloAntes && window.CoachStoryStyles && typeof window.CoachStoryStyles.fijar === 'function') window.CoachStoryStyles.fijar(estiloAntes);
    }
  }
  const storyFotoBtn = document.getElementById('storyFotoBtn');
  const storyFotoInput = document.getElementById('storyFotoInput');
  const storyFotoQuitar = document.getElementById('storyFotoQuitar');
  if(storyFotoBtn && storyFotoInput){
    storyFotoBtn.addEventListener('click', function(){ storyFotoInput.click(); });
    storyFotoInput.addEventListener('change', function(e){
      const f = e.target.files[0]; if(!f) return;
      const r = new FileReader();
      r.onload = function(){
        const img = new Image();
        img.onload = function(){
          window.__storyFotoImg = img;
          if(storyFotoQuitar) storyFotoQuitar.style.display = 'inline-block';
          redibujarStoryActual();
          try{ toast('📷 Foto de fondo aplicada'); }catch(x){}
        };
        img.onerror = function(){ try{ toast('No se pudo leer esa imagen', 'err'); }catch(x){} };
        img.src = r.result;
      };
      r.readAsDataURL(f);
      e.target.value = '';
    });
  }
  if(storyFotoQuitar){
    storyFotoQuitar.addEventListener('click', function(){
      window.__storyFotoImg = null;
      storyFotoQuitar.style.display = 'none';
      redibujarStoryActual();
    });
  }
  document.getElementById('storyX').addEventListener('click', function(){
    /* la foto no sobrevive a cerrar el modal -- cada Story Card arranca
       limpia con el fondo táctico por defecto, nunca arrastra la foto de
       una sesión vieja a la sesión siguiente sin que el alumno la suba de nuevo */
    window.__storyFotoImg = null;
    if(storyFotoQuitar) storyFotoQuitar.style.display = 'none';
  });

  /* FASE 2.5 -- datos del Story Card de Bodybuilding extraídos a función
     propia (antes vivían sólo adentro del click del botón de
     .summary-card) para poder reusarlos también desde el CTA fijo de
     cierre de sesión (ver el guardrail en renderMain(): "sólo CrossFit"
     pasa a incluir Bodybuilding también, cada uno con su propia función
     de datos -- CF sigue con datosStoryCF() tal cual, sin tocar). */
  function datosStorySports(weekIdx, day){
    const r = (window.CoachTV && window.CoachTV.resumen) ? window.CoachTV.resumen(weekIdx, day) : { vol:0, series:0, reps:0 };
    const ini = (state.session && state.session.inicio) || 0;
    const elapsedMin = ini ? Math.round((Date.now() - ini) / 60000) : 0;
    /* GUARDIÁN DE TIEMPO (directiva crítica) -- state.session.inicio se
       setea una sola vez por sesión y nunca se resetea (ver
       _marcarInicioSesion/latido()), así que si pasó mucho tiempo real
       desde el primer set trackeado el cálculo "ingenuo" daba minutos
       absurdos (ej. 28774 MIN, o "13h 41m" reportado en producción).
       Se acota a un rango de sesión creíble (1 a 180 min) y, si el valor
       no es creíble o no hay registro real, se cae a una estimación
       coherente en base a las series completadas (20-180 min, 60 por
       defecto si no hay series). */
    const minsCrudo = (elapsedMin >= 1 && elapsedMin <= 150) ? elapsedMin : (r.series > 0 ? Math.min(150, Math.max(20, r.series * 3)) : 60);
    const tiempoFmt = fmtDuracionStory(minsCrudo);
    const f = new Date();
    /* directiva (aislamiento de PRs por día) -- mismo criterio que
       pintarResumen(): state.session.prs es un log de nombres de TODO el
       mesociclo que nunca se resetea (esto era lo que hacía aparecer,
       ej., "Bulgarian Split Squat" como PR destacado en un día de
       empuje). Se filtra state.session.prDetalle (trae fecha) por HOY y
       por pertenencia real a un ejercicio de ESTE día. */
    const hoyISO = f.toISOString().slice(0, 10);
    const nombresHoy = {};
    (day.blocks || []).forEach(function(b){
      if(b.exerciseName) nombresHoy[nrmHist(b.exerciseName)] = 1;
      (b.exercises || []).forEach(function(e){ if(e.name) nombresHoy[nrmHist(e.name)] = 1; });
    });
    const vistosPr = {};
    const prsHoy = ((state.session && state.session.prDetalle) || [])
      .filter(function(p){ return p.fecha === hoyISO && nombresHoy[nrmHist(p.ex)]; })
      .map(function(p){ return p.ex; })
      .filter(function(nombre){ if(vistosPr[nombre]) return false; vistosPr[nombre] = 1; return true; });
    return {
      atleta: PROGRAM_CONFIG.athleteName || 'Atleta',
      fecha: f.toLocaleDateString('es-AR', { day:'2-digit', month:'long', year:'numeric' }),
      sesion: (day.short || '') + ' · ' + (day.label || ''),
      disciplina: (PROGRAM_CONFIG.mesoName || 'Coach JP') + ' — ' + (WEEKS_META[weekIdx] || {}).name,
      /* directiva (fix integral StoryCard): día/semana y título de la
         sesión por separado -- "sesion"/"disciplina" de arriba quedan
         intactos (los sigue leyendo champion()), estos son sólo para
         el nuevo encabezado de 3 líneas de dibujar(). */
      diaCorto: day.short || '',
      semanaN: (weekIdx || 0) + 1,
      tituloSesion: day.label || (day.short || 'Sesión'),
      vol: r.vol, series: r.series, reps: r.reps, tiempo: tiempoFmt,
      semanaNom: String((WEEKS_META[weekIdx] || {}).phase || ''),
      prs: prsHoy
    };
  }
  /* ---------- botón dentro del Session Summary ---------- */
  function inyectarBoton(){
    const acts = document.querySelector('.summary-card .sc-actions');
    if(!acts || document.getElementById('scStory')) return;
    const b = document.createElement('button');
    b.className = 'sc-story'; b.id = 'scStory'; b.type = 'button';
    b.textContent = window.COACH_DISCIPLINA === 'sports' ? '📸 GENERAR STORY CARD' : '📸 Generar Story Card';
    acts.insertBefore(b, acts.firstChild);
    b.addEventListener('click', function(){
      const day = DAYS.find(function(x){ return x.id === state.currentDay; }) || DAYS[0];
      abrirStory(datosStorySports(state.currentWeek, day));
    });
  }
  const _rm = renderMain;
  renderMain = function(){
    const r = _rm.apply(this, arguments);
    try{ anillo(); fase(); titulo(); setTimeout(inyectarBoton, 60); }catch(e){ console.warn('skin', e); }
    return r;
  };
  /* el resumen aparece cuando se completa el día: se observa el main */
  const obs = new MutationObserver(function(){ try{ inyectarBoton(); }catch(e){} });

  /* ---------- badge dinámico de fase del mesociclo ---------- */
  function fase(){
    const el = document.getElementById('hdPhase'); if(!el) return;
    const w = WEEKS_META[state.currentWeek] || {};
    const nombre = (w.phase || w.name || '').toString();
    el.textContent = 'Fase ' + (state.currentWeek + 1) + ': ' + nombre;
    el.classList.toggle('deload', !!w.deload || /deload|descarga/i.test(nombre));
    el.classList.toggle('peak', /pico|fallo|peak/i.test(nombre));
    el.style.display = nombre ? '' : 'none';
  }
  /* ---------- título con separador dorado ---------- */
  function titulo(){
    const h = document.querySelector('.hd-banner h1'); if(!h || h.dataset.jp) return;
    h.dataset.jp = '1';
    /* "Fuerza Pesada, <em>Densidad Metabólica.</em>" → "FUERZA PESADA • DENSIDAD METABÓLICA" */
    h.innerHTML = h.innerHTML
      .replace(/,\s*(?=<em)/i, '&nbsp;<span class="hd-dot">&bull;</span> ')
      .replace(/,\s*$/, '')
      .replace(/\.\s*(<\/em>)/i, '$1')
      .replace(/\.\s*$/, '');
  }

  /* la barra de días se pega justo debajo de la de semanas */
  function medir(){
    const w = document.querySelector('.week-selector-wrap');
    if(!w) return;
    document.documentElement.style.setProperty('--wsel-h', Math.round(w.getBoundingClientRect().height) + 'px');
  }
  /* =========================================================
     PWA DEL ALUMNO · manifiesto, service worker e instalación
  ========================================================= */
  /* iconos diferenciados por app (misma silueta de escudo facetado):
       bb  Bodybuilding -> escudo titanio con filo cobre + mancuerna angular
       cf  CrossFit     -> escudo mate con acento cian/verde neón + cronómetro */
  /* icono OFICIAL de Coach JP (escudo dorado con rayo), el mismo para Bodybuilding y CrossFit: PNG real embebido (180 / 192 / 512), nunca dibujado ni generico */
  const JP_ICONOS = { 180: 'data:image/png;base64,', 192: 'data:image/png;base64,', 512: 'data:image/png;base64,' };
  function iconoPNG(size){ return size <= 180 ? JP_ICONOS[180] : (size <= 192 ? JP_ICONOS[192] : JP_ICONOS[512]); }
  function pwaMetas(){
    const nombre = (PROGRAM_CONFIG.athleteName || 'Mi rutina');
    const add = (sel, attrs) => {
      if(document.querySelector(sel)) return;
      const el = document.createElement('meta');
      Object.keys(attrs).forEach(k => el.setAttribute(k, attrs[k]));
      document.head.appendChild(el);
    };
    add('meta[name="apple-mobile-web-app-capable"]', { name:'apple-mobile-web-app-capable', content:'yes' });
    add('meta[name="apple-mobile-web-app-status-bar-style"]',
        { name:'apple-mobile-web-app-status-bar-style', content:'black-translucent' });
    const nombreApp = window.COACH_DISCIPLINA === 'crossfit' ? 'Coach JP Crossfit' : 'Coach JP Bodybuilding';
    add('meta[name="apple-mobile-web-app-title"]', { name:'apple-mobile-web-app-title', content:nombreApp });
    add('meta[name="theme-color"]', { name:'theme-color', content:'#0A0A0A' });
    /* Android arma la app instalable (WebAPK) en un servidor que descarga los iconos por URL: los data: URI y los blob: no se pueden bajar y
       Chrome termina creando un simple acceso directo. Servido por http(s) los iconos van como URL publica real (PNG del sitio oficial de Coach JP, CORS abierto). */
    const http = /^https?:$/.test(location.protocol);
    const PWA_BASE = 'https://juampiarmi.github.io/Coach-JP---Program-Builder/';
    const icono = function(px, mask){ return http ? PWA_BASE + 'icon-' + px + (mask ? '-maskable' : '') + '.png' : iconoPNG(px); };
    const iniciaUrl = http ? (location.origin + location.pathname + location.search) : location.href;
    const m = {
      name: nombreApp + ' \u2022 Performance Program',
      short_name: nombreApp,
      description: 'Planificación personalizada de ' + nombre + ' — Coach JP Performance System',
      start_url: iniciaUrl,
      scope: iniciaUrl.replace(/[?#].*$/, '').replace(/[^/]*$/, ''),
      id: window.COACH_DISCIPLINA === 'crossfit' ? 'coachjp-athlete-cf' : 'coachjp-athlete-bb',
      display: 'standalone',
      display_override: ['standalone', 'minimal-ui'],
      prefer_related_applications: false,
      background_color: '#0A0A0A',
      theme_color: '#0A0A0A',
      orientation: 'portrait-primary',
      lang: 'es-AR',
      categories: ['health','fitness','sports'],
      icons: [
        { src: icono(192), sizes:'192x192', type:'image/png', purpose:'any' },
        { src: icono(512), sizes:'512x512', type:'image/png', purpose:'any' },
        { src: icono(192, true), sizes:'192x192', type:'image/png', purpose:'maskable' },
        { src: icono(512, true), sizes:'512x512', type:'image/png', purpose:'maskable' }
      ]
    };
    let link = document.querySelector('link[rel="manifest"]');
    if(!link){ link = document.createElement('link'); link.rel = 'manifest'; document.head.appendChild(link); }
    link.href = URL.createObjectURL(new Blob([JSON.stringify(m)], { type:'application/manifest+json' }));
    let ic = document.querySelector('link[rel="apple-touch-icon"]');
    if(!ic){ ic = document.createElement('link'); ic.rel = 'apple-touch-icon'; document.head.appendChild(ic); }
    ic.setAttribute('sizes', '180x180'); ic.href = iconoPNG(180);
  }
  function pwaSW(){
    if(!('serviceWorker' in navigator) || location.protocol === 'file:') return;
    /* 09/09 -- antes esto era cache-first: una vez que el celular del
       alumno guardaba una versión, la servía para siempre y nunca volvía
       a pedirle nada al servidor, así se subiera una versión nueva. Eso
       podía explicar una app "mezclada" (una versión vieja del acordeón
       conviviendo con contenido nuevo). Ahora es network-first: si hay
       conexión, siempre trae la versión más fresca del servidor y de paso
       refresca la caché; sólo usa lo guardado si está sin conexión. El
       nombre de caché también se subió de versión y las cachés viejas se
       borran solas al activarse, para no dejar basura de versiones previas. */
    const src =
      "const CACHE='coachjp-athlete-v3';" +
      "self.addEventListener('install',e=>self.skipWaiting());" +
      "self.addEventListener('activate',e=>e.waitUntil(Promise.all([" +
        "caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==CACHE&&k.indexOf('coachjp-athlete-')===0).map(k=>caches.delete(k))))," +
        "self.clients.claim()" +
      "])));" +
      "self.addEventListener('fetch',e=>{if(e.request.method!=='GET')return;" +
        "e.respondWith(fetch(e.request,{cache:'no-cache'}).then(res=>{" +
        "if(!res||res.status!==200||res.type==='opaque')return res;const c=res.clone();caches.open(CACHE).then(k=>k.put(e.request,c));return res;})" +
        ".catch(()=>caches.match(e.request).then(r=>r||caches.match(location.href))));});" +
      /* directiva 13, capa 2: infraestructura para push remotas. Ningún
         backend de esta app manda pushes todavía (no hay servidor de
         suscripciones ni claves VAPID) -- esto sólo deja el SW listo para
         RECIBIR un payload JSON del día en que exista ese envío remoto,
         mostrándolo con el mismo idioma visual (título/cuerpo/vibración)
         que ya usa la notificación local de descanso de abajo. */
      "self.addEventListener('push',e=>{" +
        "let d={};try{d=e.data?e.data.json():{};}catch(err){}" +
        "const title=d.title||'Coach JP';" +
        "const opts={body:d.body||'',icon:d.icon,badge:d.badge,vibrate:d.vibrate||[200,100,200],data:d.data||d,tag:d.tag||'coachjp'};" +
        "e.waitUntil(self.registration.showNotification(title,opts));" +
      "});" +
      "self.addEventListener('notificationclick',e=>{" +
        "e.notification.close();" +
        "e.waitUntil(self.clients.matchAll({type:'window',includeUncontrolled:true}).then(list=>{" +
          "for(const c of list){if('focus' in c)return c.focus();}" +
          "if(self.clients.openWindow)return self.clients.openWindow('./');" +
        "}));" +
      "});" +
      /* directiva maestra ("Background timer"): aviso agendado por la página
         con el timestampFin absoluto del descanso/timer (ver jpBgTimer). Se
         muestra SÓLO si ninguna ventana de la app está visible; best effort
         (el SO puede dormir el SW). Mismo código que sw.js. */
      "let jpT=null,jpRes=null;" +
      "self.addEventListener('message',e=>{const d=e.data||{};if(d.tipo!=='jp-timer')return;" +
        "if(jpT){clearTimeout(jpT);jpT=null;}if(jpRes){jpRes();jpRes=null;}" +
        "if(d.accion!=='programar')return;const ms=d.at-Date.now();if(!(ms>0)||ms>600000)return;" +
        "e.waitUntil(new Promise(res=>{jpRes=res;jpT=setTimeout(()=>{jpT=null;jpRes=null;" +
          "self.clients.matchAll({type:'window',includeUncontrolled:true}).then(list=>{" +
            "if(list.some(c=>c.visibilityState==='visible'))return;" +
            "return self.registration.showNotification(d.titulo||'Coach JP',{body:d.cuerpo||'',vibrate:[200,100,200],tag:'coachjp-timer',renotify:true});" +
          "}).then(res,res);},ms);}));" +
      "});";
    /* updateViaCache:'none' + update(): el propio sw.js nunca se sirve del caché HTTP, así una versión nueva se detecta en cada arranque */
    navigator.serviceWorker.register('./sw.js', { updateViaCache: 'none' }).then(function(reg){ try{ reg.update(); }catch(e0){} }).catch(function(){
      try{
        const u = URL.createObjectURL(new Blob([src], { type:'text/javascript' }));
        navigator.serviceWorker.register(u).catch(function(){});
      }catch(e){}
    });
  }
  let pwaEvt = window.__jpPwaEvt || null;
  window.addEventListener('beforeinstallprompt', function(e){
    e.preventDefault(); pwaEvt = e;
    const b = document.getElementById('pwaAth');
    if(b){ b.style.display = ''; }
  });
  window.addEventListener('appinstalled', function(){
    try{ localStorage.setItem('coachjp_pwa_rol','athlete'); }catch(e){}
    const b = document.getElementById('pwaAth');
    if(b){ b.classList.add('ok'); b.textContent = '✅ Rutina instalada en tu celular'; }
  });
  function pwaBoton(){
    if(document.getElementById('pwaAth')) return;
    const standalone = window.matchMedia('(display-mode: standalone)').matches || navigator.standalone;
    const w = document.createElement('div');
    w.className = 'pwa-wrap';
    const b = document.createElement('button');
    b.className = 'pwa-athlete'; b.id = 'pwaAth'; b.type = 'button';
    b.textContent = standalone ? '✅ Rutina instalada en tu celular' : '📲 Instalar mi Rutina en el Celular';
    if(standalone) b.classList.add('ok');
    b.addEventListener('click', function(){
      if(!pwaEvt && window.__jpPwaEvt) pwaEvt = window.__jpPwaEvt;
      if(pwaEvt){
        pwaEvt.prompt();
        pwaEvt.userChoice.then(function(r){
          if(r && r.outcome === 'accepted'){ try{ localStorage.setItem('coachjp_pwa_rol','athlete'); }catch(e){} }
          pwaEvt = null;
        });
        return;
      }
      const iOS = /iphone|ipad|ipod/i.test(navigator.userAgent);
      alert(iOS
        ? 'En iPhone o iPad: tocá Compartir en Safari y elegí «Agregar a pantalla de inicio». Tu rutina queda como una app.'
        : 'Abrí el menú del navegador (⋮) y elegí «Instalar aplicación» o «Agregar a la pantalla de inicio».');
    });
    w.appendChild(b);
    const cred = document.querySelector('.hd-cred');
    if(cred && cred.parentNode) cred.parentNode.insertBefore(w, cred.nextSibling);
    else document.body.insertBefore(w, document.body.firstChild);
  }

  /* directiva maestra ("Modal Onboarding de Instalación PWA") -- guía
     táctica de 2 pasos según OS, mostrada UNA sola vez (primera apertura
     de un alumno/a nuevo) y sólo si la app todavía no corre standalone.
     No reemplaza el botón manual pwaBoton() de arriba: éste queda intacto
     para que el alumno pueda reabrir la instalación cuando quiera. */
  function mostrarGuiaPWAInstalacion(){
    /* directiva ("Refactor final"): el cartel emergente de "Entendido" se retira por completo;
       la instalación sigue disponible en el botón manual (pwaBoton) */
    return;
    if(document.querySelector('.jp-pwaguide-overlay')) return;
    const standalone = window.matchMedia('(display-mode: standalone)').matches || navigator.standalone;
    if(standalone){
      try{ localStorage.setItem('jp_pwa_guide_viewed', '1'); }catch(e){}
      return;
    }
    let visto = false;
    try{ visto = localStorage.getItem('jp_pwa_guide_viewed') === '1'; }catch(e){}
    if(visto) return;
    const iOS = /iphone|ipad|ipod/i.test(navigator.userAgent);
    const pasos = iOS ? [
      { ic: '⎋', tx: 'Pulsá el ícono de <strong>Compartir</strong> abajo en Safari (el cuadrado con la flecha hacia arriba).' },
      { ic: '⊞', tx: 'Deslizá y elegí <strong>«Agregar a inicio»</strong>.' }
    ] : [
      { ic: '⋮', tx: 'Pulsá el menú de <strong>tres puntos</strong> arriba a la derecha.' },
      { ic: '⊞', tx: 'Elegí <strong>«Instalar aplicación»</strong> o <strong>«Agregar a la pantalla principal»</strong>.' }
    ];
    const overlay = document.createElement('div');
    overlay.className = 'jp-pwaguide-overlay';
    overlay.innerHTML =
      '<div class="jp-pwaguide-pop">' +
        '<div class="jp-pwaguide-title">📲 Instalación táctica de la app</div>' +
        '<div class="jp-pwaguide-sub">' + (iOS ? 'iPhone / iPad · Safari' : 'Android · Chrome') + '</div>' +
        '<div class="jp-pwaguide-steps">' +
          pasos.map(function(p, i){
            return '<div class="jp-pwaguide-step">' +
              '<div class="jp-pwaguide-step-n">' + (i + 1) + '</div>' +
              '<div class="jp-pwaguide-step-ic">' + p.ic + '</div>' +
              '<div class="jp-pwaguide-step-tx">' + p.tx + '</div>' +
            '</div>';
          }).join('') +
        '</div>' +
        '<button type="button" class="jp-pwaguide-ok">Entendido · Ingresar al sistema</button>' +
      '</div>';
    document.body.appendChild(overlay);
    const cerrar = function(){
      try{ localStorage.setItem('jp_pwa_guide_viewed', '1'); }catch(e){}
      overlay.remove();
    };
    overlay.querySelector('.jp-pwaguide-ok').addEventListener('click', cerrar);
    overlay.addEventListener('click', function(e){ if(e.target === overlay) cerrar(); });
  }

  function mount(){
    badge(); anillo(); inyectarBoton(); fase(); titulo();
    pwaMetas(); pwaSW(); pwaBoton();
    mostrarGuiaPWAInstalacion();
    medir();
    [120, 400, 1000].forEach(function(ms){ setTimeout(medir, ms); });
    window.addEventListener('resize', medir, { passive:true });
    if(document.fonts && document.fonts.ready) document.fonts.ready.then(medir).catch(function(){});
    const m = document.getElementById('mainContent');
    if(m) obs.observe(m, { childList:true, subtree:true });
    /* marca de tiempo de inicio de sesión para la Story Card: antes se fijaba
       al tocar "Iniciar Entrenamiento" (05/09: botón retirado); ahora se
       dispara sola, en silencio, en la primera interacción real del alumno
       (un check o una carga de kg/reps), sin depender de ningún botón. */
    function _marcarInicioSesion(e){
      if(!e.target || !e.target.closest) return;
      if(!e.target.closest('.set-check, .set-input, .block-done-cb')) return;
      state.session = state.session || {};
      if(state.session.inicio) return;
      state.session.inicio = Date.now();
      saveProgress();
    }
    document.addEventListener('change', _marcarInicioSesion);
    document.addEventListener('input', _marcarInicioSesion);
      window.CoachPWA = { icono: iconoPNG, boton: pwaBoton, rol: 'athlete' };
    window.CoachStory = { abrir: abrirStory, abrirCF: abrirCF, datosSports: datosStorySports, dibujar: dibujar, dibujarCF: dibujarCF, cerrar: cerrarStory };
    window.CoachFmtDuracion = fmtDuracionStory;
  }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', mount);
  else mount();
})();
